For~\eqref{eq:channel}--\eqref{eq:cost},
\begin{equation}
 \begin{aligned}
 C_M^{\rm G}(T)=\max_{\substack{\mathbf{K}_U\succeq\mathbf{0}\\
 \operatorname{tr}(\mathbf{Q}_K\mathbf{K}_U)\leq P_MT}}\;&\frac{1}{2}\log_2\det\!\bigl(\mathbf{I}+\\[-1mm]
 &\mathbf{R}_{Z,K}^{-1/2}\mathbf{G}_K\mathbf{K}_U\mathbf{G}_K^{\mathsf T}
 \mathbf{R}_{Z,K}^{-1/2}\bigr),
 \end{aligned}                                                                      \label{eq:logdet}
\end{equation}
where $\mathbf{K}_U$ denotes the covariance matrix of $\mathbf{U}$.

\begin{equation}
 C_M^{\rm G}(T)=\max_{\substack{p_\ell\geq0\\\sum_{\ell=1}^{L(T)}p_\ell\leq P_MT}}
 \frac{1}{2}\sum_{\ell=1}^{L(T)}\log_2(1+\lambda_\ell p_\ell),                  \label{eq:parallel}
\end{equation}
The optimal resource allocation is
\begin{equation}
 p_\ell^\star
 =
 \left(\nu-\frac{1}{\lambda_\ell}\right)^+,
 \qquad
 \sum_{\ell=1}^{L(T)}p_\ell^\star=P_MT,
 \label{eq:waterfill}
\end{equation}
where $\nu$ is the water level.

\begin{equation}
 R_M^{\rm G}
 \triangleq
 \lim_{T\to\infty}\frac{C_M^{\rm G}(T)}{T}
 =
 \frac{B_M}{2}\log_2(1+\mathrm{MNR}),
 \label{eq:shannonlike}
\end{equation}
where $\mathrm{MNR} \triangleq \frac{\lambda P_M}{B_M}$, $\frac{C_M^{\rm G}(T)}{T}$ denotes the finite-horizon mobility information rate.
